package com.mandu.liquiddialer
import androidx.compose.ui.test.*
import com.mandu.liquiddialer.data.*
import com.mandu.liquiddialer.ui.*
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.*
import java.io.File
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class CanvasLayoutUiTest:CallCanvasUiFixture(){
 private val layoutSketch=listOf(CallCanvas.Stroke(1,2,listOf(CallCanvas.Point(1000,1000),CallCanvas.Point(2000,2500),CallCanvas.Point(3000,1000))),CallCanvas.Stroke(2,2,listOf(CallCanvas.Point(4500,3500),CallCanvas.Point(5500,3500),CallCanvas.Point(5500,4500),CallCanvas.Point(4500,4500),CallCanvas.Point(4500,3500))),CallCanvas.Stroke(3,3,listOf(CallCanvas.Point(7000,7000),CallCanvas.Point(9000,8000))))
 private fun open(night:Boolean=false,empty:Boolean=false){seed(night);if(!empty)CallCanvas.save(ctx,number,"",layoutSketch);rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CanvasLayoutWorkspace(number,{})}}};await{rule.onAllNodesWithTag("layout_paper",true).fetchSemanticsNodes().isNotEmpty()}}
 private fun enable(){runBlocking{ctx.repo.set(K.canvasLayout,true)};await{LdApp.settings.value.canvasLayout}}
 private fun dialog(tag:String){rule.onNodeWithTag(tag,true).performClick();settle()}
 @After fun resetLayout(){runBlocking{ctx.repo.set(K.canvasLayout,false)}}
 @Test fun defaultOffEntryAndUnsavedGuard(){show();rule.onAllNodesWithTag("canvas_layout_open",true).assertCountEquals(0);enable();await{rule.onAllNodesWithTag("canvas_layout_open",true).fetchSemanticsNodes().isNotEmpty()};rule.onNodeWithTag("canvas_layout_open",true).assertIsEnabled();stroke();rule.onNodeWithTag("canvas_layout_open",true).assertIsNotEnabled();assertEquals(sketch,CallCanvas.read(ctx,number).strokes)}
 @Test fun alignPreviewUndoRedoExplicitSave(){open();click("layout_pick_0");click("layout_pick_1");click("layout_left");rule.onNodeWithTag("layout_state",true).assertTextEquals("Unsaved layout preview");assertEquals(layoutSketch,CallCanvas.read(ctx,number).strokes);click("layout_undo");rule.onNodeWithTag("layout_state",true).assertTextEquals("Saved canvas");click("layout_redo");click("layout_save");val expected=CanvasLayout.apply(layoutSketch,setOf(0,1),CanvasLayout.Edit.LEFT);await{CallCanvas.read(ctx,number).strokes==expected};assertEquals(layoutSketch.last(),expected.last())}
 @Test fun requiredSelectionCountsAndDeselect(){open();rule.onNodeWithTag("layout_left",true).assertIsNotEnabled();click("layout_pick_0");rule.onNodeWithTag("layout_nudge_left",true).assertIsEnabled();rule.onNodeWithTag("layout_left",true).assertIsNotEnabled();click("layout_pick_1");rule.onNodeWithTag("layout_left",true).assertIsEnabled();rule.onNodeWithTag("layout_space_x",true).assertIsNotEnabled();click("layout_all");rule.onNodeWithTag("layout_space_x",true).assertIsEnabled();click("layout_none");rule.onNodeWithTag("layout_count",true).assertTextEquals("0 selected / 3 strokes")}
 @Test fun horizontalSpacingAndNudgeKeepsStyle(){open();click("layout_all");click("layout_space_x");click("layout_nudge_up");click("layout_save");val expected=CanvasLayout.apply(CanvasLayout.apply(layoutSketch,setOf(0,1,2),CanvasLayout.Edit.SPACE_X),setOf(0,1,2),CanvasLayout.Edit.NUDGE_UP);await{CallCanvas.read(ctx,number).strokes==expected};assertTrue(CallCanvas.read(ctx,"+441234567890").strokes.isEmpty())}
 @Test fun edgeRejectionIsAtomicNoDirtyOrUndo(){seed();val edge=listOf(layoutSketch[0].copy(points=listOf(CallCanvas.Point(0,0),CallCanvas.Point(1000,1000))),layoutSketch[1]);CallCanvas.save(ctx,number,"",edge);rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CanvasLayoutWorkspace(number,{})}}};await{rule.onAllNodesWithTag("layout_all",true).fetchSemanticsNodes().isNotEmpty()};click("layout_all");click("layout_nudge_left");rule.onNodeWithTag("layout_status",true).assertTextContains("whole edit refused",substring=true);rule.onNodeWithTag("layout_save",true).assertIsNotEnabled();rule.onNodeWithTag("layout_undo",true).assertIsNotEnabled();assertEquals(edge,CallCanvas.read(ctx,number).strokes)}
 @Test fun staleSaveDoesNotReplaceNewerCanvas(){open();click("layout_all");click("layout_top");val old=CallCanvas.read(ctx,number);val newer=listOf(layoutSketch.first());CallCanvas.save(ctx,number,old.raw,newer);click("layout_save");await{rule.onAllNodesWithTag("layout_error",true).fetchSemanticsNodes().isNotEmpty()};assertEquals(newer,CallCanvas.read(ctx,number).strokes);rule.onNodeWithTag("layout_state",true).assertTextEquals("Unsaved layout preview");click("layout_reload");dialog("layout_keep");rule.onNodeWithTag("layout_state",true).assertTextEquals("Unsaved layout preview");click("layout_reload");dialog("layout_discard");await{rule.onAllNodesWithTag("layout_count",true).fetchSemanticsNodes().any{it.config.getOrElse(androidx.compose.ui.semantics.SemanticsProperties.Text){emptyList()}.any{it.text=="0 selected / 1 strokes"}}}}
 @Test fun corruptReadPreservedNoFalseEmpty(){seed();val f=File(ctx.filesDir,"call_canvas.json");f.writeText("bad canvas");rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CanvasLayoutWorkspace(number,{})}}};await{rule.onAllNodesWithTag("layout_error",true).fetchSemanticsNodes().isNotEmpty()};rule.onAllNodesWithTag("layout_empty",true).assertCountEquals(0);rule.onAllNodesWithTag("layout_save",true).assertCountEquals(0);assertEquals("bad canvas",f.readText())}
 @Test fun entryReturnReloadsSavedLayoutAndNoIntent(){show();enable();click("canvas_layout_open");await{rule.onAllNodesWithTag("layout_paper",true).fetchSemanticsNodes().isNotEmpty()};click("layout_all");click("layout_left");click("layout_save");await{CallCanvas.read(ctx,number).strokes!=sketch};click("page_back");await{rule.onAllNodesWithTag("canvas_paper",true).fetchSemanticsNodes().isNotEmpty()};rule.onNodeWithTag("canvas_state",true).assertTextEquals("Saved · 3 strokes");assertNull(org.robolectric.Shadows.shadowOf(rule.activity).nextStartedActivity)}
 @Test fun discardBackPreservesFile(){open();click("layout_all");click("layout_top");click("page_back");dialog("layout_keep");rule.onNodeWithTag("layout_state",true).assertTextEquals("Unsaved layout preview");assertEquals(layoutSketch,CallCanvas.read(ctx,number).strokes)}
 @Test fun emptyCanvasNoSelectionAndSaveDisabled(){open(empty=true);rule.onNodeWithTag("layout_empty",true).assertExists();rule.onNodeWithTag("layout_all",true).assertIsNotEnabled();rule.onNodeWithTag("layout_save",true).assertIsNotEnabled()}
 @Test fun dayPreviewAndToolsPixels(){open();click("layout_all");click("layout_left");scrollTo("layout_paper");settle();saveShot(rule,"LAYOUT431-day-paper");scrollTo("layout_save");settle();saveShot(rule,"LAYOUT431-day-tools")}
 @Test fun nightLargeAndSettingsPixels(){open(true);click("layout_all");click("layout_nudge_up");scrollTo("layout_paper");settle();saveShot(rule,"LAYOUT431-night-large");scrollTo("layout_save");settle();saveShot(rule,"LAYOUT431-night-tools");assertTrue(SettingsFinder.all.any{it.id=="canvas-layout"&&it.route=="callcanvas"});rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CallCanvasPage({})}}};settle();saveShot(rule,"LAYOUT431-settings");assertFalse(LdSettings().canvasLayout)}
 @Test fun confirmedDiscardReturnsWithoutSaving(){seed();CallCanvas.save(ctx,number,"",layoutSketch);var closed=false;rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{Sheet({}){CanvasLayoutWorkspace(number,{closed=true},inSheet=true)}}}};await{rule.onAllNodesWithTag("layout_all",true).fetchSemanticsNodes().isNotEmpty()};click("layout_all");click("layout_top");click("layout_back");dialog("layout_discard");assertTrue(closed);assertEquals(layoutSketch,CallCanvas.read(ctx,number).strokes)}

}
